    id: randomUUID(),
    home: client.cliHome,
    endpoint: client.endpoint,
    identity,
    scope,
    peer,
    workspace,
    host,
    model: args.model,
    instruction: args.instruction,
    turns: args.turns,
    expiresAt: new Date(Date.now() + args.hours * 3600000).toISOString(),
    cliBinary: client.binary,
    maxProjects: 1,
