        else body += `<pre>${escape(file.bytes.toString('utf8'))}</pre>`;
        notes.push(
          `## ${title}\n\n文件：[${file.label}](${name})\n\n${file.image ? '' : file.bytes.toString('utf8')}\n`,
        );
      }
    }
    notes.push(
      `来源说明：${artifact.provenance || '未提供'}\n\n提交者自检：${artifact.verification || '未提供'}\n`,
    );
