  const child = spawn(policy.host.binary, ['--print-logs', 'acp'], {
    cwd: policy.workspace,
    env,
    windowsHide: true,
    detached: process.platform !== 'win32',
    stdio: ['pipe', 'pipe', 'pipe'],
  });
